package org.apache.commons.math.fraction;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.ZeroException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.ArithmeticUtils;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class BigFraction_doubleValue_TriageGen0Test {

    private static final double DELTA = 1e-15;

    @Test
    public void testDoubleValue_IntegerInputs() {
        BigFraction fraction = new BigFraction(1, 2);
        assertEquals(0.5, fraction.doubleValue(), DELTA);
    }

    @Test
    public void testDoubleValue_LongInputs() {
        BigFraction fraction = new BigFraction(5L, 2L);
        assertEquals(2.5, fraction.doubleValue(), DELTA);
    }

    @Test
    public void testDoubleValue_BigIntegerInputs() {
        BigInteger num = new BigInteger("10");
        BigInteger den = new BigInteger("3");
        BigFraction fraction = new BigFraction(num, den);
        assertEquals(3.3333333333333335, fraction.doubleValue(), DELTA);
    }

    @Test
    public void testDoubleValue_NegativeValues() {
        BigFraction fraction = new BigFraction(-1, 4);
        assertEquals(-0.25, fraction.doubleValue(), DELTA);

        BigFraction fraction2 = new BigFraction(1, -4);
        assertEquals(-0.25, fraction2.doubleValue(), DELTA);

        BigFraction fraction3 = new BigFraction(-1, -4);
        assertEquals(0.25, fraction3.doubleValue(), DELTA);
    }

    @Test
    public void testDoubleValue_ZeroNumerator() {
        BigFraction fraction = new BigFraction(0, 5);
        assertEquals(0.0, fraction.doubleValue(), DELTA);
    }

    @Test
    public void testDoubleValue_ZeroDenominator() {
        // BigFraction usually prevents zero denominator in constructor, 
        // but if we test the mathematical behavior of the double conversion:
        BigFraction fraction = new BigFraction(new BigInteger("1"), new BigInteger("0"));
        // Note: In standard Math, 1.0 / 0.0 is Double.POSITIVE_INFINITY
        // However, BigFraction constructor throws MathIllegalArgumentException for zero denominator.
        // This test assumes we are testing the doubleValue method logic assuming valid objects.
    }

    @Test
    public void testDoubleValue_LargeValues() {
        // Test values that exceed the capacity of a double to ensure precision/overflow handling
        BigInteger largeNum = BigInteger.TEN.pow(400);
        BigInteger largeDen = BigInteger.TEN.pow(399);
        BigFraction fraction = new BigFraction(largeNum, largeDen);
        assertEquals(10.0, fraction.doubleValue(), DELTA);
    }

    @Test
    public void testDoubleValue_VerySmallValues() {
        BigInteger num = BigInteger.ONE;
        BigInteger den = BigInteger.TEN.pow(400);
        BigFraction fraction = new BigFraction(num, den);
        // Should result in 0.0 as it's smaller than Double.MIN_VALUE
        assertEquals(0.0, fraction.doubleValue(), DELTA);
    }

    @Test
    public void testDoubleValue_OverflowToInfinity() {
        // Numerator much larger than denominator capacity
        BigInteger num = BigInteger.TEN.pow(400);
        BigInteger den = BigInteger.ONE;
        BigFraction fraction = new BigFraction(num, den);
        assertEquals(Double.POSITIVE_INFINITY, fraction.doubleValue(), DELTA);
    }

    @Test
    public void testDoubleValue_FromDoubleConstructor() {
        BigFraction fraction = new BigFraction(0.75);
        assertEquals(0.75, fraction.doubleValue(), DELTA);
    }
}
